package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/planning/comments") public class PlanningCommentController {private final PlanningCommentService s;public PlanningCommentController(PlanningCommentService s){this.s=s;} @PostMapping public Mono<PlanningCommentView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody CreatePlanningCommentRequest r){return s.create(a,r);}@GetMapping public Flux<PlanningCommentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@RequestParam PlanningCommentTargetType targetType,@RequestParam UUID targetId){return s.list(o,targetType,targetId);}@PatchMapping("/{commentId}")public Mono<PlanningCommentView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID commentId,@Valid@RequestBody UpdatePlanningCommentRequest r){return s.update(a,commentId,r);}@DeleteMapping("/{commentId}")public Mono<Void> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID commentId){return s.delete(a,commentId);}}
